/* Native gesture scrolling; smooth section links respect reduced motion. */
(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)');const clamp=y=>Math.max(0,Math.min(y,document.documentElement.scrollHeight-innerHeight));document.addEventListener('click',event=>{if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const link=event.target.closest?.('a[href^="#"]');if(!link||link.closest('.chapter-tabs')||link.hasAttribute('download'))return;const hash=link.getAttribute('href');let destination;if(hash==='#')destination=0;else{let section;try{section=document.getElementById(decodeURIComponent(hash.slice(1)))}catch{}if(!section)return;destination=section.getBoundingClientRect().top+scrollY-document.querySelector('nav').getBoundingClientRect().height-16}event.preventDefault();if(location.hash!==hash)history.pushState(null,'',hash);window.scrollTo({top:clamp(destination),behavior:reduced.matches?'instant':'smooth'})});
})();
